module TreasureSolver(\n    input clk,\n    input rst_n,\n    input start,\n    input [1:0] char_arr [0:15],\n    input [4:0] length,\n    output reg [7:0] assign_arr [0:7],\n    output reg [3:0] num_hashes,\n    output reg done,\n    output reg fail\n);\n    // State declarations\n    localparam [2:0] IDLE      = 3'd0;\n    localparam [2:0] COUNT     = 3'd1;\n    localparam [2:0] CALC      = 3'd2;\n    localparam [2:0] VERIFY    = 3'd3;\n    localparam [2:0] FINISH_OK = 3'd4;\n    localparam [2:0] FINISH_ERR= 3'd5;\n    reg [2:0] state, next_state;\n\n    // Counters\n    reg [5:0] open_count;\n    reg [5:0] close_count;\n    reg [3:0] hash_count;\n    reg [4:0] count_index;\n    \n    // Assignment\n    reg [7:0] last_assign;\n\n    // Verification\n    reg signed [15:0] balance;\n    reg [4:0] verify_index;\n    reg [3:0] current_hash;\n    reg valid;\n\n    // Hash storage\n    reg [4:0] hash_positions [0:7];\n\n    // Cycle counter\n    reg [5:0] cycle_count;\n\n    integer i; // Loop variable\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            done <= 1'b0;\n            fail <= 1'b0;\n            open_count <= 6'd0;\n            close_count <= 6'd0;\n            hash_count <= 4'd0;\n            count_index <= 5'd0;\n            cycle_count <= 6'd0;\n            verify_index <= 5'd0;\n            current_hash <= 4'd0;\n            balance <= 16'd0;\n            valid <= 1'b0;\n            for (i = 0; i < 8; i = i + 1) begin\n                assign_arr[i] <= 8'd0;\n                hash_positions[i] <= 5'd0;\n            end\n            num_hashes <= 4'd0;\n            last_assign <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    fail <= 1'b0;\n                    cycle_count <= 6'd0;\n                    if (start) begin\n                        state <= COUNT;\n                        open_count <= 6'd0;\n                        close_count <= 6'd0;\n                        hash_count <= 4'd0;\n                        count_index <= 5'd0;\n                        // Reset hash positions\n                        for (i = 0; i < 8; i = i + 1) begin\n                            hash_positions[i] <= 5'd0;\n                        end\n                    end\n                end\n\n                COUNT: begin\n                    if (count_index < length) begin\n                        if (char_arr[count_index] == 2'b00) begin\n                            open_count <= open_count + 6'd1;\n                        end else if (char_arr[count_index] == 2'b01) begin\n                            close_count <= close_count + 6'd1;\n                        end else if (char_arr[count_index] == 2'b10) begin\n                            if (hash_count < 4'd8) begin\n                                // Store hash position (Icarus-safe method)\n                                case (hash_count)\n                                    4'd0: hash_positions[0] <= count_index;\n                                    4'd1: hash_positions[1] <= count_index;\n                                    4'd2: hash_positions[2] <= count_index;\n                                    4'd3: hash_positions[3] <= count_index;\n                                    4'd4: hash_positions[4] <= count_index;\n                                    4'd5: hash_positions[5] <= count_index;\n                                    4'd6: hash_positions[6] <= count_index;\n                                    4'd7: hash_positions[7] <= count_index;\n                                endcase\n                                hash_count <= hash_count + 4'd1;\n                            end\n                        end\n                        count_index <= count_index + 5'd1;\n                    end else begin\n                        state <= CALC;\n                    end\n                end\n\n                CALC: begin\n                    last_assign <= open_count - close_count - hash_count + 6'd2;\n                    if (last_assign < 8'd1 || (open_count + close_count + hash_count) == 6'd0) begin\n                        fail <= 1'b1;\n                        state <= FINISH_ERR;\n                    end else begin\n                        // Setup verification state\n                        verify_index <= 5'd0;\n                        current_hash <= 4'd0;\n                        balance <= 16'd0;\n                        valid <= 1'b1;\n                        state <= VERIFY;\n                    end\n                end\n\n                VERIFY: begin\n                    if (verify_index < length) begin\n                        if (char_arr[verify_index] == 2'b00) begin\n                            balance <= balance + 16'd1;\n                        end else if (char_arr[verify_index] == 2'b01) begin\n                            balance <= balance - 16'd1;\n                        end else if (char_arr[verify_index] == 2'b10) begin\n                            if (current_hash == hash_count - 4'd1) begin\n                                balance <= balance - last_assign;\n                            end else begin\n                                balance <= balance - 16'd1;\n                            end\n                            current_hash <= current_hash + 4'd1;\n                        end\n\n                        if (balance < 16'sd0) begin\n                            valid <= 1'b0;\n                        end\n\n                        verify_index <= verify_index + 5'd1;\n                    end else begin\n                        if (valid && (balance == 16'sd0)) begin\n                            state <= FINISH_OK;\n                        end else begin\n                            state <= FINISH_ERR;\n                        end\n                    end\n                end\n\n                FINISH_OK: begin\n                    // Populate assignments\n                    for (i = 0; i < 8; i = i + 1) begin\n                        if (i < hash_count) begin\n                            assign_arr[i] <= (i == hash_count - 4'd1) ? last_assign : 8'd1;\n                        end else begin\n                            assign_arr[i] <= 8'd0;\n                        end\n                    end\n                    num_hashes <= hash_count;\n                    done <= 1'b1;\n                    fail <= 1'b0;\n                    state <= IDLE;\n                end\n\n                FINISH_ERR: begin\n                    done <= 1'b1;\n                    fail <= 1'b1;\n                    // Clear outputs\n                    for (i = 0; i < 8; i = i + 1) begin\n                        assign_arr[i] <= 8'd0;\n                    end\n                    num_hashes <= 4'd0;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n\n            // Prevent infinite loops\n            cycle_count <= cycle_count + 6'd1;\n            if (cycle_count >= 6'd32) begin\n                state <= FINISH_ERR;\n            end\n        end\n    end\nendmodule\n